from deepagent_files import input_path, publish_path
import json, io

p = input_path("L_08bf77e2-f489-4649-bedb-ae6f02f752c1")
with io.open(p, "r", encoding="utf-8") as f:
    data = json.load(f)

# discover structure
def find_pages(obj):
    if isinstance(obj, dict):
        for key in ("pages", "page_list", "result_pages", "data"):
            if key in obj and isinstance(obj[key], list):
                return obj[key], key
        for vv in obj.values():
            r = find_pages(vv)
            if r:
                return r
    return None, None

pages, key = find_pages(data)
info = {"top_keys": list(data.keys())[:20], "pages_key": key, "page_count": len(pages) if pages else 0}
if pages:
    sample = pages[0]
    info["page_item_keys"] = list(sample.keys()) if isinstance(sample, dict) else str(type(sample))
    texts = []
    for pg in pages:
        if isinstance(pg, dict):
            pn = pg.get("page_num") or pg.get("page") or pg.get("pageNum") or pg.get("page_index")
            t = pg.get("text") or pg.get("markdown") or pg.get("content") or ""
            texts.append("===== PAGE %s =====\n%s" % (pn, t))
    full = "\n".join(texts)
    out_p = publish_path("ocr-pages-4-13.txt", mime="text/plain; charset=utf-8")
    with io.open(out_p, "w", encoding="utf-8") as g:
        g.write(full)
    info["total_chars"] = len(full)
    info["page_lens"] = [len(t) for t in texts]
info
